calleeMethods:
static inline bool is_kvmppc_hv_enabled(struct kvm *kvm) /* <=== is_kvmppc_hv_enabled */ 
{
	return kvm->arch.kvm_ops == kvmppc_hv_ops;
}

static inline bool early_cpu_has_feature(unsigned long feature) /* <=== early_cpu_has_feature */ 
{
	return !!((CPU_FTRS_ALWAYS & feature) ||
		  (CPU_FTRS_POSSIBLE & cur_cpu_spec->cpu_features & feature));
}

static inline bool cpu_has_feature(unsigned long feature) /* <=== cpu_has_feature */ 
{
	return early_cpu_has_feature(feature);
}

